def fib_ref(n: int) -> int:
    """Obviously-correct reference model: F0=0, F1=1, Fn=Fn-1+Fn-2."""
    assert n >= 0
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

